(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};

  // 文件由 --file-input 塞进「打开作品」，等导入完成
  for (let i = 0; i < 40; i++) {
    await sleep(500);
    if (document.querySelector('.pj-title') || document.querySelector('.tb-error')) break;
  }
  out.opened = document.querySelector('.pj-title')?.textContent || null;
  out.diffBadge = document.querySelector('.pj-diff')?.textContent || null;

  // ① 卍解作品打开后应该有程序代码区，且代码在里面
  out.hasCodePanel = !!document.querySelector('.pc-wrap');
  out.codeFile = document.querySelector('.pc-item-name')?.textContent || null;
  out.codeVisible = (document.querySelector('.pc-code')?.textContent || '').includes('pinMode(9, OUTPUT)');

  const projects = await s.listProjects();
  const p = projects.find((x) => x.name.includes('卍解测试'));
  out.storedDifficulty = p?.difficulty;
  out.storedCodeCount = p?.codeCount;
  const files = await s.listCodeFiles(p.id);
  out.storedCode = files.map((f) => ({ name: f.name, lang: f.language, note: f.note }));

  // ② 回列表：始解作品不该有程序代码区（回归）
  document.querySelector('.pj-crumb-link')?.click();
  await sleep(2000);
  const shikaiCard = [...document.querySelectorAll('.tb-project-main')].find((c) => (c.innerText || '').includes('循迹小车'));
  out.shikaiCardBadge = shikaiCard ? ((shikaiCard.innerText || '').match(/始解|卍解/) || [null])[0] : null;
  shikaiCard?.click();
  await sleep(3400);
  out.shikaiTitle = document.querySelector('.pj-title')?.textContent || null;
  out.shikaiHasCodePanel = !!document.querySelector('.pc-wrap');
  out.shikaiDiffBadge = document.querySelector('.pj-diff')?.textContent || null;
  out.shikaiStillHasBom = !!document.querySelector('.pj-card-title');
  return JSON.stringify(out);
})()
